package io.github.ningpp.compat;

/** Replacement for System.Globalization.CultureNotFoundException (generated by CSharpToJava converter). */
public class CultureNotFoundException extends IllegalArgumentException {
    public CultureNotFoundException() { super(); }
    public CultureNotFoundException(String message) { super(message); }
    public CultureNotFoundException(String message, Throwable cause) { super(message, cause); }
}
